// Checks authored callable documentation and parameter layout contracts.
#include "source_contracts.h"

#include "source_contracts_internal.h"

#include <iostream>
#include <regex>

namespace
{
// Excludes function declarations generated by authored GoogleTest macros.
bool generated_test(CXCursor cursor)
{
    CXFile file = nullptr;
    unsigned offset = 0;
    clang_getSpellingLocation(clang_getCursorLocation(cursor), &file, nullptr,
                              nullptr, &offset);
    if (file == nullptr)
        return false;
    const auto source = quality::detail::read_source(
        quality::detail::text(clang_getFileName(file)));
    return std::regex_search(
        source.substr(offset),
        std::regex("^(TEST|TEST_F|TEST_P|TYPED_TEST|TYPED_TEST_P)\\s*\\("));
}
} // namespace

namespace quality
{
bool SourceContracts::documented(CXCursor cursor) const
{
    const auto comment = detail::text(clang_Cursor_getRawCommentText(cursor));
    if (!detail::descriptive(comment))
        return false;
    CXFile file = nullptr;
    unsigned offset = 0;
    clang_getSpellingLocation(
        clang_getRangeStart(clang_Cursor_getCommentRange(cursor)), &file,
        nullptr, nullptr, &offset);
    return file != nullptr &&
           offset >= detail::header_end(detail::read_source(
                         detail::text(clang_getFileName(file))));
}

void SourceContracts::inspect_function(CXCursor cursor)
{
    if (generated_test(cursor))
        return;
    auto key = detail::text(clang_getCursorUSR(cursor));
    if (key.empty())
        key = detail::location(cursor);
    if (detail::text(clang_getCursorSpelling(cursor)) == "main")
    {
        CXFile file = nullptr;
        clang_getSpellingLocation(clang_getCursorLocation(cursor), &file,
                                  nullptr, nullptr, nullptr);
        key += ":" + detail::text(clang_getFileName(file));
    }
    auto& contract = functions_[key];
    contract.location = detail::location(cursor);
    contract.documented |=
        documented(cursor) || documented(clang_getCanonicalCursor(cursor));

    unsigned previous_end = 0;
    for (const auto parameter : detail::parameters(cursor))
    {
        unsigned first = 0;
        unsigned last = 0;
        const auto range = clang_getCursorExtent(parameter);
        clang_getSpellingLocation(clang_getRangeStart(range), nullptr, &first,
                                  nullptr, nullptr);
        clang_getSpellingLocation(clang_getRangeEnd(range), nullptr, &last,
                                  nullptr, nullptr);
        if (previous_end >= first)
        {
            std::cerr << detail::location(cursor)
                      << ": parameters must occupy separate lines\n";
            failed_ = true;
        }
        previous_end = last;
    }
}
} // namespace quality
